// Demo samples: the single list used by the /demo/ viewer, the /demo/samples/ page, the prebuild
// step that fetches third-party files (scripts/prebuild.d/10-samples.mjs) and the sample tests.
//
// Own samples are synthetic drawings generated by our scripts. They are committed, except the
// large one ("atBuild"), which the prebuild step generates into public/samples/generated/
// (git-ignored). Third-party samples are fetched at build time from a pinned upstream commit and
// verified against their SHA-256; they are git-ignored (public/samples/third-party/) and never
// come from client data.
// Keep this file free of non-erasable TypeScript syntax: Node imports it directly.

export type SampleId = 'plan-dxf' | 'site-dxf' | 'citygml-building' | 'citygml-district' | 'contours-dxf' | 'dwg-acadsharp' | 'dgn-v8-gdal' | 'dgn-v7-gdal';

export interface SampleUpstream {
	/** GitHub owner/name. */
	repo: string;
	/** Full commit SHA the file and its licence are fetched from. */
	commit: string;
	/** Path of the file in the upstream repository. */
	path: string;
	/** Path of the licence file in the upstream repository (same commit). */
	licensePath: string;
	/** Committed copy of the licence text (relative to the site root). */
	licenseCopy: string;
	/** Expected SHA-256 of the file (hex); the build fails on any other content. */
	sha256: string;
	/** Expected size in bytes. */
	bytes: number;
}

export interface Sample {
	id: SampleId;
	/** Short name for the picker. */
	label: string;
	/** One sentence on what the drawing shows. */
	description: string;
	/** Format as shown to readers. */
	format: string;
	/** Path under public/ (and URL path on the site). */
	path: string;
	/** Licence of the file itself (SPDX expression). */
	license: string;
	/** Who made the drawing. */
	origin: string;
	/**
	 * Part of the drawing the viewer shows first, as [minX, minY, maxX, maxY] in drawing units,
	 * for sheets too wide to read when fitted whole. "Fit" shows everything.
	 */
	start?: readonly [number, number, number, number];
	/** Own samples: the script that generates the file (it exports buildSample()). */
	generator?: string;
	/** Own samples: the file is not committed; the prebuild step runs the generator. */
	atBuild?: boolean;
	upstream?: SampleUpstream;
}

