/** Raw download URL of an upstream file at its pinned commit. */
export const rawUrl = (u: SampleUpstream, path: string = u.path): string =>
	`https://raw.githubusercontent.com/${u.repo}/${u.commit}/${path}`;

/** Human-readable URL of an upstream file at its pinned commit. */
export const blobUrl = (u: SampleUpstream, path: string = u.path): string =>
	`https://github.com/${u.repo}/blob/${u.commit}/${path}`;

/** Site URL of the licence text served for an upstream sample. */
export const licenseHref = (u: SampleUpstream): string =>
	`/demo/samples/licenses/${u.licenseCopy.split('/').pop()}`;

export const sampleById = (id: string): Sample | undefined => SAMPLES.find((s) => s.id === id);
